                Assert.NotEqual(AtmStatus.DispenserFault, result.Status);
            }
        }
    }

    // ───────────────────────── Retraits en plusieurs passages avec le vrai module ─────────────────────────

    [Fact]
    public void Withdraw200_ElevenNotesInSeveralPasses_EmptiesTheModule()
    {
